package com.horabase.api.request;
import com.horabase.api.business.*;import com.horabase.api.employee.*;import com.horabase.api.request.dto.ResolveEmployeeRequest;import com.horabase.api.shift.ShiftRepository;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.Optional;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.when;
@ExtendWith(MockitoExtension.class)class EmployeeRequestServiceTests{@Mock EmployeeRequestRepository repo;@Mock BusinessRepository businesses;@Mock EmployeeRepository employees;@Mock ShiftRepository shifts;@Test void approvesPendingRequest(){Business b=new Business();ReflectionTestUtils.setField(b,"id",1L);Employee e=new Employee();ReflectionTestUtils.setField(e,"id",2L);e.setFirstName("Ana");e.setLastName("Pérez");EmployeeRequest r=new EmployeeRequest();ReflectionTestUtils.setField(r,"id",3L);r.setBusiness(b);r.setEmployee(e);r.setType(EmployeeRequestType.DAY_OFF);r.setTitle("Día libre");r.setDescription("Motivo");r.setStatus(EmployeeRequestStatus.PENDING);when(repo.findByIdAndBusiness_Id(3L,1L)).thenReturn(Optional.of(r));when(repo.save(r)).thenReturn(r);EmployeeRequestService s=new EmployeeRequestService(repo,businesses,employees,shifts,Clock.fixed(Instant.parse("2026-08-13T14:00:00Z"),ZoneOffset.UTC));var out=s.resolve(1L,3L,EmployeeRequestStatus.APPROVED,new ResolveEmployeeRequest("Aprobado"));assertThat(out.status()).isEqualTo(EmployeeRequestStatus.APPROVED);assertThat(out.adminResponse()).isEqualTo("Aprobado");assertThat(out.resolvedAt()).isEqualTo(OffsetDateTime.parse("2026-08-13T14:00:00Z"));}}
